(CASE WHEN {x} IS NULL OR {y} IS NULL THEN CAST(NULL AS DOUBLE PRECISION) WHEN {x} = 'NaN' OR {y} = 'NaN' OR {y} = 0 OR abs({x}) = 'Infinity' THEN CAST('NaN' AS DOUBLE PRECISION) WHEN abs({y}) = 'Infinity' OR {x} = 0 OR abs({x}) < abs({y}) THEN {x} ELSE sign({x}) * CAST(round(mod(CAST(CAST(abs({x}) * power(CAST(2 AS DOUBLE PRECISION), div((60 - CAST(floor(ln(abs({x})) / ln(2)) AS INTEGER)), 2)) * power(CAST(2 AS DOUBLE PRECISION), (60 - CAST(floor(ln(abs({x})) / ln(2)) AS INTEGER)) - div((60 - CAST(floor(ln(abs({x})) / ln(2)) AS INTEGER)), 2)) AS BIGINT) AS NUMERIC) * power(CAST(2 AS NUMERIC), greatest((60 - CAST(floor(ln(abs({y})) / ln(2)) AS INTEGER)), 0) - (60 - CAST(floor(ln(abs({x})) / ln(2)) AS INTEGER))), CAST(CAST(abs({y}) * power(CAST(2 AS DOUBLE PRECISION), div((60 - CAST(floor(ln(abs({y})) / ln(2)) AS INTEGER)), 2)) * power(CAST(2 AS DOUBLE PRECISION), (60 - CAST(floor(ln(abs({y})) / ln(2)) AS INTEGER)) - div((60 - CAST(floor(ln(abs({y})) / ln(2)) AS INTEGER)), 2)) AS BIGINT) AS NUMERIC) * power(CAST(2 AS NUMERIC), greatest((60 - CAST(floor(ln(abs({y})) / ln(2)) AS INTEGER)), 0) - (60 - CAST(floor(ln(abs({y})) / ln(2)) AS INTEGER)))), 1000) / power(CAST(2 AS NUMERIC), greatest((60 - CAST(floor(ln(abs({y})) / ln(2)) AS INTEGER)), 0)) AS DOUBLE PRECISION) END)